"""Real official-compiler fixtures and bounded malformed-container controls."""
from __future__ import annotations

import hashlib
import unittest

from mpy_bytecode import (
    MAX_CONSTANT_NODES, MAX_DEPTH, MAX_MPY_BYTES, MAX_RAW_CODES, MAX_TABLE_ITEMS,
    MPYBytecodeError, validate_bytecode,
)


# Generated by the unchanged official mpy-cross at MicroPython commit
# 78ff170de9e32c79db6e64d3e33d2bd60002bdcd (v1.27.0 / mpy v6.3).
# Tool and full source stay in .work. These small inline fixtures are test data,
# never imported/executed on the host or a guest by this suite.
# helper.py, -msmall-int-bits=31 -s helper.py:
# TAG = "official-mpy-cross-78ff170d"
# def transform(value): return value * 3 + 7
# def describe(value, pressed):
#     return "%s:%d:%s" % (TAG, transform(value), "DOWN" if pressed else "UP")
HELPER = bytes.fromhex(
    "4d06001f0a011268656c7065722e7079000f127472616e73666f726d00106465736372"
    "696265001025733a25643a25730008444f574e0004555000065441470082450e707265"
    "7373656400051b6f6666696369616c2d6d70792d63726f73732d3738666631373064"
    "00811c0006014464230016073200160232011603516302581106020860b083f487f2"
    "6381682a0a0308096060100412071202b03401b144441005424210062a03f863"
)
# native-control.py, additionally -march=xtensawin:
# import micropython
# @micropython.native
# def f(value): return value + 1
NATIVE = bytes.fromhex(
    "4d062b1f0501226e61746976652d636f6e74726f6c2e7079000f8167026600824500"
    "81040804012680511b021602320016035163018441000000000600000036a1000901"
    "78126827783778072261010c3aa26104a2c104bd03cd04dd0582272de00800422108"
    "0c3cbd041cba822712e008002d0ac6ffff08011df01104030444"
)
# constants.py: A = (None, False, True, Ellipsis, b"\x00abc", "中文",
#                    9999999999999999999999, 1.25, 2j)
CONSTANTS = bytes.fromhex(
    "4d06001f050418636f6e7374616e74732e7079000f0ce4b8ade69687004702410006"
    "0400616263000716393939393939393939393939393939393939393939390804312e"
    "32350902326a81404002015150521103230010022301230223032a0916045163"
)
# A for/try/finally/break function, including signed UNWIND_JUMP and int -123456.
FLOW = bytes.fromhex(
    "4d06001f05000e666c6f772e7079000f08776f726b00814d81774c00020132001602"
    "51630182304d100203202522234429b05f4b13c14907b14443404b81511204b13401"
    "595d422b22f8bb4063"
)
# def outer(value):
#     def inner(other=2): return value + other
#     return inner
CLOSURE = bytes.fromhex(
    "4d06001f070014636c6f737572652e7079000f0a6f75746572000a696e6e65720082"
    "450b0a6f74686572004c00020132001602516301811421090204204900822a0153b0"
    "210001c1b16301609a0108030506402500b1f263"
)
# def f(*, a0, a1, ... a15): return a0
# The official compiler needs six bytes for this interleaved signature.
KEYWORD16 = bytes.fromhex(
    "4d06001f13000e6b7731362e7079000f026600046130000461310004613200046133"
    "00046134000461350004613600046137000461380004613900066131300006613131"
    "0006613132000661313300066131340006613135004c000201320016025163018158"
    "8090808080082402030405060708090a0b0c0d0e0f10111220b063"
)


def uint(value):
    result = [value & 127]
    value >>= 7
    while value:
        result.insert(0, 0x80 | (value & 127))
        value >>= 7
    return bytes(result)


def qstr(value=b"fixture.py"):
    return uint(len(value) << 1) + value + b"\x00"


# S=1, no args; source info has the simple-name qstr 0; load None; return.
BODY = b"\x00\x02\x00\x51\x63"


def code(body=BODY, children=(), kind=0):
    return (uint((len(body) << 3) | (4 if children else 0) | kind) + body
            + (uint(len(children)) + b"".join(children) if children else b""))


def module(raw_code=None, objects=(), strings=None):
    strings = [qstr()] if strings is None else strings
    return (b"M\x06\x00\x1f" + uint(len(strings)) + uint(len(objects))
            + b"".join(strings) + b"".join(objects)
            + (code() if raw_code is None else raw_code))


class MPYBytecodeTests(unittest.TestCase):
    def test_real_official_compiler_helper_is_recursively_bytecode(self):
        self.assertEqual(hashlib.sha256(HELPER).hexdigest(),
                         "583a0028999b53b0ba576f0a2c79c6a7cb2b7243b91725215e3de284a18a41fd")
        result = validate_bytecode(HELPER)
        self.assertEqual(result, {
            "mpy_version": 6, "small_int_bits": 31, "feature_byte": 0,
            "native_arch": 0, "raw_code_count": 3, "qstr_count": 10,
            "object_count": 1, "constant_node_count": 1,
            "max_raw_code_depth": 2, "bytecode_bytes": 59,
            "instruction_count": 27,
        })

    def test_real_unicode_bytes_bigint_float_complex_and_closure_fixtures(self):
        self.assertEqual(validate_bytecode(CONSTANTS)["object_count"], 4)
        self.assertEqual(validate_bytecode(CLOSURE)["max_raw_code_depth"], 3)
        self.assertEqual(validate_bytecode(FLOW)["raw_code_count"], 2)

    def test_interleaved_preludes_are_not_limited_like_seven_bit_varuints(self):
        self.assertEqual(validate_bytecode(KEYWORD16)["raw_code_count"], 2)
        # S=65, A=64, source-info bytes=65; bit fields from py/bc.h.
        positional64 = bytes.fromhex("8080908080048202") + b"\x00" * 65 + b"\x51\x63"
        self.assertEqual(validate_bytecode(module(code(positional64)))["raw_code_count"], 1)
        # S=33, I=1, C=32 requires six interleaved prelude-size bytes.
        cells32 = bytes.fromhex("802082808080800100") + bytes(range(32)) + b"\x51\x63"
        self.assertEqual(validate_bytecode(module(code(cells32)))["raw_code_count"], 1)
        with self.assertRaisesRegex(MPYBytecodeError, "argument locals"):
            validate_bytecode(module(code(b"\x02\x06\x00\x00\x00\x51\x63")))

    def test_official_compiler_isolated_surrogates_remain_data(self):
        # A="\\ud800", compiled as a qstr; A=("\\ud800", "\\udfff") as objects.
        for fixture in (
            "4d06001f040018737572726f676174652e7079000f06eda0800002410048000201100216035163",
            "4d06001f0301247475706c655f737572726f676174652e7079000f0241000a020503eda080000503edbfbf0048000201230016025163",
        ):
            self.assertEqual(validate_bytecode(bytes.fromhex(fixture))["raw_code_count"], 1)

    def test_native_compiler_artifact_and_forged_header_are_rejected(self):
        self.assertEqual(hashlib.sha256(NATIVE).hexdigest(),
                         "b5ef441586ff7dcfecce9c826fd7739db34ddb95400868161a2531789d2eb2ce")
        with self.assertRaisesRegex(MPYBytecodeError, "native architecture"):
            validate_bytecode(NATIVE)
        spoof = bytearray(NATIVE)
        spoof[2] = 0  # A caller can forge this field; inspect the payload too.
        with self.assertRaisesRegex(MPYBytecodeError, "function-table"):
            validate_bytecode(bytes(spoof))
        self.assertEqual(spoof[33], 0)
        spoof[33] = 1  # Also hide its native function-table constant as None.
        with self.assertRaisesRegex(MPYBytecodeError, "native raw-code"):
            validate_bytecode(bytes(spoof))

    def test_all_native_kinds_are_rejected_at_root_and_nested_depths(self):
        for kind in (1, 2, 3):
            for raw in (code(kind=kind), code(children=[code(children=[code(kind=kind)])])):
                with self.subTest(kind=kind), self.assertRaisesRegex(MPYBytecodeError, "native raw-code"):
                    validate_bytecode(module(raw))

    def test_every_truncation_of_real_compiler_file_fails_closed(self):
        for length in range(len(HELPER)):
            with self.subTest(length=length), self.assertRaises(MPYBytecodeError):
                validate_bytecode(HELPER[:length])

    def test_header_minor_is_ignored_for_bytecode_but_future_major_is_not(self):
        for minor in range(4):
            self.assertEqual(validate_bytecode(HELPER[:2] + bytes([minor]) + HELPER[3:])["feature_byte"], minor)
        for replacement in (b"N\x06", b"M\x05", b"M\x07"):
            with self.assertRaises(MPYBytecodeError):
                validate_bytecode(replacement + HELPER[2:])
        for flags in (4, 0x40, 0x80, 0xff):
            with self.assertRaises(MPYBytecodeError):
                validate_bytecode(HELPER[:2] + bytes([flags]) + HELPER[3:])
        for bits in (0, 65, 255):
            with self.assertRaises(MPYBytecodeError):
                validate_bytecode(HELPER[:3] + bytes([bits]) + HELPER[4:])

    def test_size_type_and_trailing_data_limits(self):
        for value in (None, "M", bytearray(HELPER), b"M" * (MAX_MPY_BYTES + 1), HELPER + b"\x00"):
            with self.subTest(value=type(value).__name__), self.assertRaises(MPYBytecodeError):
                validate_bytecode(value)

    def test_qstr_counts_static_ids_utf8_and_terminators_are_bounded(self):
        for counts in ((0, 0), (MAX_TABLE_ITEMS + 1, 0), (1, MAX_TABLE_ITEMS + 1)):
            with self.assertRaises(MPYBytecodeError):
                validate_bytecode(b"M\x06\x00\x1f" + uint(counts[0]) + uint(counts[1]))
        for string in (b"\x01", uint((166 << 1) | 1), qstr(b"\xff"), b"\x02x!", uint(999999)):
            with self.subTest(string=string), self.assertRaises(MPYBytecodeError):
                validate_bytecode(module(strings=[string]))
        self.assertEqual(validate_bytecode(module(strings=[b"\x03"]))["qstr_count"], 1)

    def test_unsigned_overlong_overflow_and_truncated_values_are_rejected(self):
        for encoded in (b"\x80\x00", b"\x81" * 6, uint(1 << 32), b"\xff"):
            with self.subTest(encoded=encoded), self.assertRaises(MPYBytecodeError):
                validate_bytecode(b"M\x06\x00\x1f" + encoded)

    def test_constant_kinds_and_text_do_not_evaluate_source(self):
        good = [bytes([kind]) for kind in range(1, 5)]
        good += [b"\x05\x00\x00", b"\x06\x00\x00", b"\x07\x02-2",
                 b"\x08\x031.5", b"\x09\x022j", b"\x0a\x02\x01\x03"]
        self.assertEqual(validate_bytecode(module(objects=good))["constant_node_count"], len(good) + 2)
        for constant in (b"\x00", b"\x0b", b"\x07\x031+2", b"\x07\x00",
                         b"\x08\x01x", b"\x09\x01x", b"\x05\x01\xff\x00",
                         b"\x06\x01x!", b"\x0a" + uint(MAX_CONSTANT_NODES + 1)):
            with self.subTest(constant=constant), self.assertRaises(MPYBytecodeError):
                validate_bytecode(module(objects=[constant]))

    def test_tuple_and_raw_code_depth_and_total_counts_are_bounded(self):
        self.assertEqual(validate_bytecode(module(objects=[b"\x0a\x01" * (MAX_DEPTH - 1) + b"\x01"]))["constant_node_count"], MAX_DEPTH)
        with self.assertRaisesRegex(MPYBytecodeError, "nesting depth"):
            validate_bytecode(module(objects=[b"\x0a\x01" * MAX_DEPTH + b"\x01"]))
        nested = code()
        for _ in range(MAX_DEPTH - 1):
            nested = code(children=[nested])
        self.assertEqual(validate_bytecode(module(nested))["max_raw_code_depth"], MAX_DEPTH)
        with self.assertRaisesRegex(MPYBytecodeError, "nesting depth"):
            validate_bytecode(module(code(children=[nested])))
        oversized = uint((len(BODY) << 3) | 4) + BODY + uint(MAX_RAW_CODES + 1)
        with self.assertRaisesRegex(MPYBytecodeError, "children count"):
            validate_bytecode(module(oversized))

    def test_aggregate_counts_apply_across_siblings_and_nested_constants(self):
        raw = code(children=[code()] * (MAX_RAW_CODES - 1))
        self.assertEqual(validate_bytecode(module(raw))["raw_code_count"], MAX_RAW_CODES)
        branch = code(children=[code()] * 128)
        with self.assertRaises(MPYBytecodeError):
            validate_bytecode(module(code(children=[branch] * 32)))
        packed_tuple = b"\x0a" + uint(MAX_CONSTANT_NODES // 2) + b"\x01" * (MAX_CONSTANT_NODES // 2)
        with self.assertRaises(MPYBytecodeError):
            validate_bytecode(module(objects=[packed_tuple, packed_tuple]))

    def test_declared_small_int_width_covers_signed_and_multi_opcodes(self):
        # Header compatibility is separate from the guest's actual width.
        for instruction in (b"\x22\x20", b"\x90"):
            value = module(code(BODY[:3] + instruction + b"\x63"))
            with self.assertRaisesRegex(MPYBytecodeError, "small integer"):
                validate_bytecode(value[:3] + b"\x05" + value[4:])

    def test_missing_child_and_out_of_range_qstr_object_and_local_indices_fail(self):
        for instructions in (b"\x10\x01\x63", b"\x23\x00\x63", b"\x32\x00\x63",
                             b"\xb1\x63", b"\x24\x01\x63"):
            with self.subTest(instructions=instructions), self.assertRaises(MPYBytecodeError):
                validate_bytecode(module(code(BODY[:3] + instructions)))
        raw = uint((len(BODY) << 3) | 4) + BODY + b"\x01"
        with self.assertRaises(MPYBytecodeError):
            validate_bytecode(module(raw))
        with self.assertRaisesRegex(MPYBytecodeError, "qstr reference"):
            validate_bytecode(module(code(b"\x01\x04\x00\x01\x51\x63")))

    def test_malformed_preludes_opcodes_operands_and_jumps_are_rejected(self):
        bodies = [b"", b"\x80" * 8, b"\x00\x80" * 8, b"\x00\x00\x51\x63",
                  b"\x00\x02\x00", b"\x00\x06\x00\x51\x63",
                  b"\x00\x04\x00\x80\x51\x63"]
        bodies += [BODY[:3] + bytes([opcode]) for opcode in (0, 0x41, 0xd4, 0xff, 0x10, 0x20, 0x40)]
        bodies += [BODY[:3] + b"\x42\x41\x63", BODY[:3] + b"\x22" + b"\xff" * 11]
        bodies += [BODY[:3] + b"\x2e" + operand + b"\x63" for operand in (b"\x01", b"\x81\x02", b"\x80\x02")]
        for body in bodies:
            with self.subTest(body=body), self.assertRaises(MPYBytecodeError):
                validate_bytecode(module(code(body)))
        self.assertEqual(validate_bytecode(module(code(BODY[:3] + b"\x42\x40\x63")))["instruction_count"], 2)
        for size in (2, 3):
            self.assertEqual(validate_bytecode(module(code(BODY[:3] + bytes((0x2e, size, 0x63)))))["instruction_count"], 2)


if __name__ == "__main__":
    unittest.main()
